def config_value(text: str, key: str) -> str:
    """Return the value for `key` in name=value per-line config text, or "" if absent."""
    result = ""
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        k, sep, v = line.partition("=")
        if not sep:
            continue
        if k.strip() == key:
            result = v.strip()
    return result


def test_config_value_found() -> None:
    text = "host=localhost\nport=8080\ndebug=true"
    assert config_value(text, "port") == "8080"
    assert config_value(text, "host") == "localhost"
    assert config_value(text, "debug") == "true"


def test_config_value_missing() -> None:
    text = "host=localhost\nport=8080"
    assert config_value(text, "missing") == ""
    assert config_value("", "port") == ""


def test_config_value_whitespace_trimmed() -> None:
    text = "  user = alice \n  password = secret "
    assert config_value(text, "user") == "alice"
    assert config_value(text, "password") == "secret"


def test_config_value_contains_equals() -> None:
    text = "query=a=1&b=2"
    assert config_value(text, "query") == "a=1&b=2"


def test_config_value_empty_value() -> None:
    text = "key="
    assert config_value(text, "key") == ""


def test_config_value_exact_key_match() -> None:
    text = "prefix_key=value1\nkey=value2\nkey_suffix=value3"
    assert config_value(text, "key") == "value2"


def test_config_value_ignores_comments_and_blank_lines() -> None:
    text = "# comment\n\nkey=value\n  \n# another comment"
    assert config_value(text, "key") == "value"


def test_config_value_last_occurrence_wins() -> None:
    text = "key=first\nkey=second"
    assert config_value(text, "key") == "second"

